<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { ArrowUpRight, Check, Loader2, MapPin, MessageCircle, Send } from 'lucide-vue-next'
import FAQ from './sections/FAQ.vue'
import CasaHero from './casa/CasaHero.vue'
import CasaAbout from './casa/CasaAbout.vue'
import CasaCare from './casa/CasaCare.vue'
import CasaTcc from './casa/CasaTcc.vue'
import CasaContact from './casa/CasaContact.vue'
import CasaFooter from './casa/CasaFooter.vue'
import FloatingWhatsapp from './casa/FloatingWhatsapp.vue'

const variants = [{ name: 'Casa', slug: 'casa' }]
const active = ref(0)
const current = computed(() => variants[active.value])
const config = useRuntimeConfig()
const form = reactive({ name: '', email: '', phone: '', message: '' })
const formState = ref('idle')
const menuOpen = ref(false)
const root = ref(null)
const heroImage = ref(null)
let revealObserver

const services = [
  ['Ansiedade e emoções', 'Reconhecer sentimentos, medos e formas mais gentis de lidar com eles.'],
  ['Escola e foco', 'Apoio para dificuldades de aprendizagem, organização e ansiedade de desempenho.'],
  ['Mundo digital', 'Construção de equilíbrio no uso de telas, jogos e nas relações presenciais.'],
  ['Habilidades sociais', 'Mais repertório para criar vínculos, comunicar-se e conviver com segurança.'],
]
const whatsapp = 'https://wa.me/5571999999999?text=Olá!%20Gostaria%20de%20saber%20mais%20sobre%20o%20atendimento.'

function scrollToContact() { document.querySelector('#contato')?.scrollIntoView({ behavior: 'smooth' }) }
async function submitForm() {
  formState.value = 'loading'
  try {
    const response = await fetch(config.public.formspreeEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({ nome: form.name, email: form.email, telefone: form.phone, mensagem: form.message }),
    })
    if (!response.ok) throw new Error('Falha no envio')
    formState.value = 'success'
    Object.assign(form, { name: '', email: '', phone: '', message: '' })
  } catch { formState.value = 'error' }
}
function handleHeroPointer(event) {
  if (!window.matchMedia('(hover: hover) and (pointer: fine)').matches || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return
  const box = event.currentTarget.getBoundingClientRect()
  const x = ((event.clientX - box.left) / box.width - .5) * 2
  const y = ((event.clientY - box.top) / box.height - .5) * 2
  if (heroImage.value) heroImage.value.style.transform = `translate3d(${x * 9}px, ${y * 7}px, 0) scale(1.035)`
}
function resetHeroPointer() { if (heroImage.value) heroImage.value.style.transform = '' }
function handleMenuKeydown(event) { if (event.key === 'Escape') menuOpen.value = false }
watch(menuOpen, (isOpen) => {
  if (!import.meta.client) return
  document.documentElement.style.overflow = isOpen ? 'hidden' : ''
})
onMounted(() => {
  window.addEventListener('keydown', handleMenuKeydown)
  if (!('IntersectionObserver' in window)) return
  revealObserver = new IntersectionObserver((entries) => entries.forEach((entry) => {
    if (entry.isIntersecting) { entry.target.dataset.visible = ''; revealObserver.unobserve(entry.target) }
  }), { threshold: .12, rootMargin: '0px 0px -60px 0px' })
  root.value?.querySelectorAll('.motion-reveal').forEach((element) => revealObserver.observe(element))
})
onBeforeUnmount(() => {
  revealObserver?.disconnect()
  window.removeEventListener('keydown', handleMenuKeydown)
  document.documentElement.style.overflow = ''
})
</script>

